    // ---------- model ----------
    function markets() {
      let pool = ZR.filter(z => z.occ >= P.minhh);
      if (P.scope === 'county' && P.counties.length) pool = pool.filter(z => P.counties.includes(z.fips));
      if (P.scope === 'picks') { const s = new Set(P.picks); pool = ZR.filter(z => s.has(z.zip)); }
      else pool = pool.sort((a, b) => b.effb - a.effb).slice(0, P.n);
      const w = pool.map(z => Math.pow(Math.max(1, z.opp_usd), P.alpha)); const ws = sum(w) || 1;
      return pool.map((z, i) => ({ z, share: w[i] / ws, spend: P.budget * w[i] / ws, es: z.span_sh >= P.spanTh, angles: anglesFor(z).filter(a => P.angles.includes(a.id)) }));
    }
    function forecast(M) {
      const out = {}; PLATS.forEach(p => { const A = P.asm[p]; const spend = P.budget * (P.mix[p] || 0) / 100; if (!spend) { out[p] = { spend: 0, clicks: 0, leads: 0, booked: 0 }; return; }
        const cm = sum(M.map(m => m.share * m.z.cpc_rel)) || 1; let clicks = 0, leads = 0;
        if (A.basis === 'CPC') { clicks = spend / (A.cost * (p === 'google' || p === 'microsoft' ? cm : 1)); leads = clicks * A.cvr / 100; }
        else if (A.basis === 'CPM') { const imp = spend / A.cost * 1000; clicks = imp * A.ctr / 100; leads = clicks * A.cvr / 100; }
        else { leads = spend / A.cost; clicks = leads; }
        const book = p === 'lsa' ? Math.min(90, P.bookRate * 1.3) : p === 'linkedin' ? 0 : P.bookRate;
        out[p] = { spend, clicks, leads, booked: leads * book / 100 }; });
      return out;
    }
    function ctxFor(z, lang) { const city = (z && z.city) || P.city; return { city, short: city.length > 12 ? city.split(' ')[0] : city, county: (z && z.cty) || '', brand: P.brand.slice(0, 25), lic: P.lic, pay: P.pay, phone: phoneFmt(P.phone) }; }
    function rsaFor(a, z, lang) {
      const ctx = ctxFor(z, lang); const src = lang === 'es' && a.es ? a.es : a;
      const hs = [], seen = new Set(); (src.h || []).concat(lang === 'es' ? ['Técnicos con Licencia', 'Llame Hoy', 'Servicio en {county}'] : ['Call {brand}', 'Serving {county} County', 'Licensed HVAC Team']).forEach(h => { const t = fillCopy(h, ctx, 30); if (t && !seen.has(t.toLowerCase()) && hs.length < 15) { seen.add(t.toLowerCase()); hs.push(t); } });
      const ds = []; (src.d || []).forEach(d => { const t = fillCopy(d, ctx, 90); if (t && !ds.includes(t) && ds.length < 4) ds.push(t); });
      if (!ds.some(d => d.includes(P.lic))) { const t = fillCopy(lang === 'es' ? 'Contratista con licencia en Texas. Lic {lic}.' : 'Licensed Texas air conditioning contractor. Lic {lic}.', ctx, 90); if (t) { if (ds.length >= 4) ds[3] = t; else ds.push(t); } }
      return { h: hs, d: ds };
    }
    const lint = (txt, extra) => satchelLint(txt, Object.assign({ lic: P.lic }, extra || {}));
    const lintSet = (texts, plat) => { const all = texts.join(' \n '); const f = lint(all, { needLic: true, platform: plat }); texts.forEach(t => lint(t, { headline: true }).forEach(x => { if (x.rule.id === 'GGL1') f.push(x); })); return f; };
    // ---------- render ----------
    let MKT = [], FC = {};
