      $('#dkLine', root).value = P.line; $('#dkBud', root).value = P.budget; $('#dkStart', root).value = P.start; $('#dkWeeks', root).value = P.weeks; $('#dkScope', root).value = P.scope;
      $$('#dkCounties option', root).forEach(o => o.selected = P.counties.includes(o.value)); $('#dkPicks', root).value = P.picks.join(', '); $('#dkN', root).value = P.n; $('#dkMin', root).value = String(P.minhh);
      $('#dkAlpha', root).value = P.alpha; $('#dkAlphaV', root).textContent = D(P.alpha, 1); $('#dkSpan', root).value = P.spanTh; $('#dkBrand', root).value = P.brand; $('#dkLic', root).value = P.lic; $('#dkPhone', root).value = P.phone; $('#dkUrl', root).value = P.url; $('#dkCity', root).value = P.city; $('#dkPay', root).value = P.pay; $('#dkBook', root).value = P.bookRate; $('#dkVal', root).value = P.jobVal;
